const menu=[['概览','dashboard','⌂'],['赛事参与','competitions','▣'],['任务中心','tasks','✓'],['报名组织','signup','✎'],['人员管理','people','♟'],['企业初赛','prelim','▤'],['成绩排名','ranking','★'],['晋级推荐','promotion','↑'],['企业数据','analytics','◫'],['通知与资料','docs','♧']];
const names=['李明','王芳','赵强','陈静','刘伟','周敏'];
