 ranking:()=>head('成绩与排名','查看本企业初赛成绩及行业排名',btn('导出成绩','export'))+table(['本企排名','姓名','工种','理论','实操','总分','行业排名'],names.map((n,i)=>`<tr><td>${i+1}</td><td>${n}</td><td>电解工</td><td>${96-i*2}</td><td>${95-i}</td><td><b>${95.5-i*1.5}</b></td><td>${12+i*7}</td></tr>`)),
 promotion:()=>head('晋级推荐','按规则生成候选人并提交组织方确认',btn('重新计算','recalc')+btn('提交推荐名单','submitPromotion',true))+`<div class="notice"><b>晋级规则：</b>企业初赛总分前 10 名，且理论与实操均不低于 60 分；企业可调整 2 名候补。</div>`+table(['选择','姓名','初赛排名','总分','建议','状态'],names.map((n,i)=>`<tr><td><input type="checkbox" ${i<5?'checked':''}></td><td>${n}</td><td>${i+1}</td><td>${95.5-i}</td><td><span class="tag green">${i<5?'推荐':'候补'}</span></td><td>${i===0?'已确认':'待提交'}</td></tr>`)),
 analytics:()=>head('企业竞赛数据','仅展示本企业授权范围内的聚合数据',btn('导出报表','export'))+`<div class="metrics"><div class="card"><small>报名率</small><b>92%</b></div><div class="card"><small>完赛率</small><b>84%</b></div><div class="card"><small>合格率</small><b>89%</b></div><div class="card"><small>平均分</small><b>81.6</b></div></div><div class="grid"><section class="panel"><h3>各部门参赛人数</h3><div class="chart">${[75,120,155,100,185].map((h,i)=>`<div class="bar" style="height:${h}px" data-x="${['电解一部','电解二部','铸造部','动力部','检修部'][i]}"></div>`).join('')}</div></section><section class="panel"><h3>成绩分布</h3><div class="list"><div>90 分以上　18%</div><div>80–89 分　42%</div><div>70–79 分　29%</div><div>70 分以下　11%</div></div></section></div>`,
