 review:()=>form('报名资格审核','<div class="field"><label>审核结果</label><select><option>通过</option><option>退回补充</option><option>不通过</option></select></div><div class="field"><label>审核意见</label><textarea placeholder="填写审核意见"></textarea></div>'),
