 questionSourceOptions:()=>form('初赛题库来源候选方案','<div class="notice"><b>待业务确认</b><p>以下方案用于需求评审，正式开发前需明确题库共享边界、企业命题权限与审核责任。</p></div><div class="list"><div><b>方案 A：平台统一题库</b><small>组织方统一提供试卷与题目版本，企业仅选择获授权试卷；规则一致、便于统一排名。</small></div><div><b>方案 B：企业自有题库</b><small>企业维护本企业题库并自行组卷；灵活度高，但需补充命题、审核和数据隔离规则。</small></div><div><b>方案 C：混合模式</b><small>统一题库为主，企业按授权比例补充自有题目；需明确难度与分值校准。</small></div></div>','关闭'),
 config:()=>form('初赛场次配置','<div class="field"><label>考试时间</label><input value="2026-07-10 14:00"></div><div class="field"><label>考试时长</label><input value="90 分钟"></div><div class="field"><label>题库/试卷来源（待业务确认）</label><select><option>候选 A：平台统一题库 · 电解工初赛 A 卷</option><option>候选 B：企业自有题库 · 千铝工投选拔卷</option><option>候选 C：平台与企业混合组卷</option></select></div><p class="muted">此选择仅演示候选交互，不代表业务方案已确认。 <button class="link" data-act="questionSourceOptions">查看方案说明</button></p>'),
 publish:()=>form('发布企业初赛','<p>发布后 251 名已审核选手将收到考试通知，确认发布？</p>','确认发布'),
